class Job:
    def __init__(self, task_id, job_id, release_time, relative_priority_point):
        self.task_id = task_id
        self.job_id = job_id
        self.release_time = release_time
        self.relative_priority_point = relative_priority_point
        self.absolute_priority_point = self.release_time + self.relative_priority_point

    def has_higher_priority_than(self, other_job):
        if self.absolute_priority_point < other_job.absolute_priority_point:
            return True
        elif self.absolute_priority_point == other_job.absolute_priority_point:
            # Arbitrary tie-breaking, e.g., by task ID then job ID
            if self.task_id < other_job.task_id:
                return True
            elif self.task_id == other_job.task_id and self.job_id < other_job.job_id:
                return True
            else:
                return False
        else:
            return False

class Job:
    def __init__(self, release_time, finish_time, ...):
        self.release_time = release_time
        self.finish_time = finish_time

    def is_active_at(self, time_t):
        return self.release_time <= time_t < self.finish_time

class Task:
    def __init__(self, task_id, jobs_list, ...):
        self.task_id = task_id
        self.jobs = jobs_list # List of Job objects for this task

    def is_active_at(self, time_t):
        for job in self.jobs:
            if job.is_active_at(time_t):
                return True
        return False

    def get_current_job_at(self, time_t):
        active_jobs = [job for job in self.jobs if job.is_active_at(time_t)]
        if not active_jobs:
            return None
        # Sort by release time to find the earliest
        active_jobs.sort(key=lambda j: j.release_time)
        return active_jobs[0]

class SchedulerState:
    def __init__(self, current_time, executing_job_id, suspending_job_id):
        self.current_time = current_time
        self.executing_job_id = executing_job_id
        self.suspending_job_id = suspending_job_id

    def is_working_on(self, job_id, time_t):
        return self.current_time == time_t and self.executing_job_id == job_id

    def is_suspended_by(self, job_id, time_t):
        return self.current_time == time_t and self.suspending_job_id == job_id

def check_not_finished_condition(job_k_l, task_k, interval_c, interval_d, schedule_simulator):
    if job_k_l.finish_time <= interval_d:
        return False # Job finished, condition not applicable
    if not task_k.is_active_at_any_point_in_interval(interval_c, interval_d): # Conceptual function
        return False # Task not active, condition not applicable

    total_blocking_time = 0
    for task_i in task_set_T:
        if task_i.id != task_k.id:
            total_blocking_time += calculate_B_i_k_l(task_i, job_k_l, interval_c, interval_d, schedule_simulator)

    total_self_work_suspend_time = 0
    # Sum WS_k_j for all jobs j <= l that are active in [c,d)
    for job_j in task_k.get_jobs_up_to(job_k_l.job_id): # Conceptual function
        total_self_work_suspend_time += calculate_WS_k_l(job_j, interval_c, interval_d, schedule_simulator)

    return (total_blocking_time + total_self_work_suspend_time) > (interval_d - interval_c)

def calculate_R_k_l_candidate(job_k_l, c, D_k, C_k, S_k, B_values_dict, WS_prev_values_list):
    # B_values_dict: {task_id: B_i_k_l_value_for_interval_c_dkl}
    # WS_prev_values_list: [WS_k_j_value_for_interval_c_dkl for j < l]

    sum_B_i_k_l = sum(B_values_dict.values())
    sum_WS_k_j = sum(WS_prev_values_list)

    R_k_l_candidate = (C_k + S_k) + sum_B_i_k_l + sum_WS_k_j + (c - job_k_l.release_time)

    if R_k_l_candidate <= D_k:
        return R_k_l_candidate
    else:
        return float('inf') # Indicates not schedulable within deadline

import math

def calculate_R_k_func(task_k, b_k, task_set_T, current_R_values, Pi_values):
    sum_interference_other_tasks = 0
    for tau_i in task_set_T:
        if tau_i.id != task_k.id:
            R_i = current_R_values[tau_i.id]
            Pi_k = Pi_values[task_k.id]
            Pi_i = Pi_values[tau_i.id]

            G_i_k = min(task_k.D - tau_i.C, Pi_k - Pi_i)

            num_interfering_jobs_numerator = G_i_k + R_i - b_k
            if num_interfering_jobs_numerator > 0:
                sum_interference_other_tasks += math.ceil(num_interfering_jobs_numerator / tau_i.T) * tau_i.C

    self_interference_jobs_count = max(0, math.floor((task_k.D - b_k) / task_k.T) - 1)
    self_interference = self_interference_jobs_count * (task_k.C + task_k.S)

    R_k_candidate = sum_interference_other_tasks + self_interference + b_k
    return R_k_candidate

def schedulability_test_fixed_window(task_set_T, Pi_values, eta, depth):
    R_values = {tau.id: tau.D for tau in task_set_T} # Initialize R_i = D_i
    ordered_tasks = sorted(task_set_T, key=lambda tau: tau.D, reverse=True)

    for _ in range(depth):
        solved_in_iteration = True
        for task_k in ordered_tasks:
            min_R_k_found = float('inf')
            step = eta * task_k.D
            b_k_candidates_limit = task_k.D
            b_k_candidates = [i * step for i in range(math.ceil(b_k_candidates_limit / step))]

            for b_k in b_k_candidates:
                current_R_k = calculate_R_k_func(task_k, b_k, task_set_T, R_values, Pi_values)
                if current_R_k <= task_k.D:
                    min_R_k_found = min(min_R_k_found, current_R_k)

            if min_R_k_found == float('inf'):
                return False # Not schedulable

            if min_R_k_found < R_values[task_k.id]:
                R_values[task_k.id] = min_R_k_found
                solved_in_iteration = False

        if solved_in_iteration:
            break

    for task_k in task_set_T:
        if R_values[task_k.id] > task_k.D:
            return False

    return True

import math

def calculate_R_k_l_candidate_variable_window(task_k, job_k_l, a, c, current_R_values, Pi_values):
    # Self-interference: at most 'a' previous jobs + current job (a+1 total)
    interval_length_from_c = (job_k_l.release_time + task_k.D) - c
    num_self_interfering_jobs = min(a + 1, math.floor(interval_length_from_c / task_k.T))
    self_interference = num_self_interfering_jobs * (task_k.C + task_k.S)

    sum_interference_other_tasks = 0
    for tau_i in task_set_T:
        if tau_i.id != task_k.id:
            R_i = current_R_values[tau_i.id]
            Pi_k = Pi_values[task_k.id]
            Pi_i = Pi_values[tau_i.id]

            G_i_k = min(task_k.D - tau_i.C, Pi_k - Pi_i)

            num_interfering_jobs_numerator = G_i_k + R_i + job_k_l.release_time - c
            if num_interfering_jobs_numerator > 0:
                sum_interference_other_tasks += math.ceil(num_interfering_jobs_numerator / tau_i.T) * tau_i.C

    R_k_l_candidate_var = self_interference + sum_interference_other_tasks + (c - job_k_l.release_time)

    if R_k_l_candidate_var <= task_k.D:
        return R_k_l_candidate_var
    else:
        return float('inf')

import math

def calculate_R_a_k_func_x(task_k, a, x, task_set_T, current_R_values, Pi_values):
    # x is the offset from r_k_l - a * T_k
    # So, c = x + r_k_l - a * T_k
    # d_k_l - c = (r_k_l + D_k) - (x + r_k_l - a * T_k) = D_k - x + a * T_k
    # r_k_l - c = r_k_l - (x + r_k_l - a * T_k) = a * T_k - x

    interval_length_from_c = task_k.D - x + a * task_k.T
    num_self_interfering_jobs = min(a + 1, math.floor(interval_length_from_c / task_k.T))
    self_interference = num_self_interfering_jobs * (task_k.C + task_k.S)

    sum_interference_other_tasks = 0
    for tau_i in task_set_T:
        if tau_i.id != task_k.id:
            R_i = current_R_values[tau_i.id]
            Pi_k = Pi_values[task_k.id]
            Pi_i = Pi_values[tau_i.id]

            num_interfering_jobs_numerator = min(task_k.D - tau_i.C, Pi_k - Pi_i) + R_i + a * task_k.T - x
            if num_interfering_jobs_numerator > 0:
                sum_interference_other_tasks += math.ceil(num_interfering_jobs_numerator / tau_i.T) * tau_i.C

    R_a_k_candidate = self_interference + sum_interference_other_tasks + (x - a * task_k.T)
    return R_a_k_candidate

def schedulability_test_variable_window(task_set_T, Pi_values, eta, max_a, depth):
    R_values = {tau.id: tau.D for tau in task_set_T}
    ordered_tasks = sorted(task_set_T, key=lambda tau: tau.D, reverse=True)

    for _ in range(depth):
        solved_in_iteration = True
        for task_k in ordered_tasks:
            min_R_k_overall = float('inf')
            found_a_tilde_k_condition = False

            for a in range(max_a + 1):
                min_R_a_k_for_current_a = float('inf')
                step = eta * task_k.D
                x_candidates_limit = a * task_k.T + task_k.D
                x_candidates = [i * step for i in range(math.ceil(x_candidates_limit / step))]

                for x in x_candidates:
                    current_R_a_k = calculate_R_a_k_func_x(task_k, a, x, task_set_T, R_values, Pi_values)
                    if current_R_a_k <= task_k.D:
                        min_R_a_k_for_current_a = min(min_R_a_k_for_current_a, current_R_a_k)

                if min_R_a_k_for_current_a <= task_k.T:
                    found_a_tilde_k_condition = True

                if min_R_a_k_for_current_a < min_R_k_overall:
                    min_R_k_overall = min_R_a_k_for_current_a
                    solved_in_iteration = False

            if not found_a_tilde_k_condition:
                return False

            if min_R_k_overall == float('inf'):
                return False

            R_values[task_k.id] = min_R_k_overall

        if solved_in_iteration:
            break

    for task_k in task_set_T:
        if R_values[task_k.id] > task_k.D:
            return False

    return True
